		return false;

	if (m_pFile == NULL)
		m_pFile = m_pFileAlloc = new CFileIO();

	bool success = m_pFile->Open(name, mode);

	if (!success)
		return false;

	SetFilename(name); /* inline in the binary */
	m_data_padded = padded_size;
